What would be the Go code to convert a CSV file with name, brand, price, and color columns to a JSON file containing details of all available Electric Toothbrushes products on a website?
Assuming the CSV file contains data only for Electric Toothbrushes products, the following Go code can be used to convert it to JSON format:
package main
import (
    "encoding/csv"
    "encoding/json"
    "fmt"
    "os"
)
type Product struct {
    Name  string `json:"name"`
    Brand string `json:"brand"`
    Price string `json:"price"`
    Color string `json:"color"`
}
func main() {
    file, err := os.Open("electric_toothbrushes.csv")
    if err != nil {
        fmt.Println(err)
    }
    defer file.Close()
    reader := csv.NewReader(file)
    records, err := reader.ReadAll()
    if err != nil {
        fmt.Println(err)
    }
    var products []Product
    for _, record := range records {
        product := Product{
            Name:  record[0],
            Brand: record[1],
            Price: record[2],
            Color: record[3],
        }
        products = append(products, product)
    }
    jsonOutput, err := json.MarshalIndent(products, "", "    ")
    if err != nil {
        fmt.Println(err)
    }
    outputFile, err := os.Create("electric_toothbrushes.json")
    if err != nil {
        fmt.Println(err)
    }
    defer outputFile.Close()
    outputFile.Write(jsonOutput)
}
Make sure to replace the file name and path with the actual CSV file location on your system.

