package main
import (
	"fmt"
	"sort"
)
type Company struct {
	Name       string
	MktCap     float64
}
type ByMktCap []Company
func (a ByMktCap) Len() int           { return len(a) }
func (a ByMktCap) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
