def breadthFirst(arrangements: Array[Array[Meat: Cheese: Vegetable]]): Array[Meat: Cheese: Vegetable] = {
    val (meat, cheese, veg) = (arrangements)

    var res = Array[Meat: Cheese: Vegetable]()
    var i, j, k = 0

    while (i < arrangements.length) {

        // prepare the next appetizer 
        val (region, ingredient) = (arrangements(i)).swap

        // check if all ingredients are the same region
        if (region == region && ingredient.filterNot(_.region == region).size == 0) {
            j = 0
            k = 0

            // find the last existing ingredient of the same region
            while (region.meat == region.cheese && j < region.cheese.length && 
                region.veg == region.meat && k < region.meat.length) {

                // get the existing ingredient in memory & create a new array 
                val tmp = region.meat.filter(ingredient.contains).toArray
                val newCheese = (cheeses :+ tmp.last) - tmp

                // update the remainder ingredient 
                ingredient.remove(tmp.last)
                newCheese.append(region.cheese.remove(tmp.last))

                // add the newly created array 
                res = res :+ (regions.append(region.name).append(newCheese).append(region.veg))

                // initialize the variables 
                j = 0
                k = 0

            }
        } 

        // prepare the next ingredient 
        val newMeat = ingredients.filter(ingredient == region).head
        val newCheese = (cheeses :+ newMeat).toArray
        val newVeg = (vegs :+ newMeat).toArray

        // update the remainder ingredient 
        ingredient.remove(newMeat)
        newCheese.append(region.cheese.remove(newMeat))
        newVeg.append(region.veg.remove(newMeat))

        // add the newly created arrays 
        res = res :+ (regions.append(region.name).append(newCheese).append(newVeg)) 
        i += 1
        j = 0
        k = 0

    }

    // return the final result 
    res
}

