function sumPositiveIntegersWithMessage($inputArray) {
    if (empty($inputArray)) {
        return 0;
    }

    $sum = 0;
    $countPositives = 0;

    foreach ($inputArray as $value) {
        if ($value >= 0) {
            $sum += $value;
            $countPositives++;
        }
