    return sum % numbers.count == 0
}
And here is the fire-related stack I want to incorporate:
var fireStack = [String]()
fireStack.append("logs")
fireStack.append("kindling")
fireStack.append("twigs")
fireStack.append("branches")
fireStack.append("logs")
Can anyone help me modify my Swift function to incorporate this fire stack? Thank you.

