```swift
import Foundation

func isSumDivisible(numbers: [Int]) -> Bool {
    var stack = ["logs", "kindling", "twigs", "branches"]

    // Initialize an empty array to store the indices to be removed
    var removableIndices: [Int] = []

    // Initialize a variable to keep track of the current sum
    var currentSum: Int = 0

    // Iterate through the numbers array
    for i in 0..<numbers.count {
        // Check if there is an element in the stack
        if !stack.isEmpty {
            // Remove the top element from the stack
            let removedElement = stack.removeLast()

            // Add the removed element to the current sum
            currentSum += removedElement.toInt() ?? 0
        }

        // Add the number at the current index to the current sum
        currentSum += numbers[i]

        // If the current sum is divisible by the number of elements in the array, remove the index of the number just added from the removableIndices array
        if currentSum % numbers.count == 0 {
            removableIndices.remove(at: i)
        }
    }

    // After iterating through the numbers array, if the current sum is divisible by the number of elements in the array, return true
    // Also, return true if all the indices in the removableIndices array are removable
    return currentSum % numbers.count == 0 && removableIndices.all { !numbers.indices.contains($0) }
}

let numbersArray = [3, 4, 5, 6, 7, 8]
print(isSumDivisible(numbers: numbersArray)) // Output: true
```
